package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.solicitudes.*;
import cl.nexbyte.siger.institucional.notificaciones.*;
import cl.nexbyte.siger.institucional.robustez.*;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
class SolicitudesTareasIndependientesTest {
 @TempDir Path p;DatosAvisosTest x;SolicitudesInstitucionales s;
 @BeforeEach void start()throws Exception{x=new DatosAvisosTest(p);s=service();}
 @AfterEach void end(){x.close();}
 SolicitudesInstitucionales service(){return new SolicitudesInstitucionales(x.d.db,x.recursos,x.cat,x.d.mapper,x.tiempo);}
 void denied(int status,org.junit.jupiter.api.function.Executable op){assertEquals(status,assertThrows(FalloTecnico.class,op).status);}
 SolicitudesInstitucionales.Edicion ed(UUID com){return new SolicitudesInstitucionales.Edicion(0,com,"Consulta sintética","Descripción reservada sintética");}
 UUID solicitud(){return s.crear(x.a(x.prof),UUID.randomUUID(),ed(x.manual())).id();}
 TareasPersonales.Edicion tarea(String type,UUID id){return new TareasPersonales.Edicion(0,"Recordatorio privado","Contenido sintético",x.tiempo.instant().minusSeconds(1),null,null,x.tiempo.instant().plusSeconds(30),"ALTA",type,id,null);}
 int count(String table){return x.d.db.sql.queryForObject("SELECT COUNT(*) FROM "+table,Integer.class);}
 @Test void baseRechazaContextosAmbiguosSinDependerDelNavegador(){UUID c=x.caso();UUID t=x.tareas.crear(x.a(x.prof),UUID.randomUUID(),tarea(null,null)).id();assertThrows(org.springframework.dao.DataAccessException.class,()->x.d.db.sql.update("UPDATE institution_task SET resource_id=? WHERE id=?",c.toString(),t.toString()));assertNull(x.tareas.leer(x.a(x.prof),t).recurso());}
 @Test void independienteEsPersonalNoCreaGestionYSeCompletaManualmente(){var key=UUID.randomUUID();var e=tarea(null,null);var r=x.tareas.crear(x.a(x.prof),key,e);assertEquals(r,x.tareas.crear(x.a(x.prof),key,e));var t=x.tareas.leer(x.a(x.prof),r.id());assertNull(t.tipoRecurso());assertNull(t.recurso());assertEquals(x.prof,t.responsable());assertEquals(0,count("core_case"));assertEquals(0,count("core_requirement"));denied(404,()->x.tareas.leer(x.a(x.ti),r.id()));denied(400,()->x.tareas.estado(x.a(x.prof),UUID.randomUUID(),r.id(),new TareasPersonales.Cambio(0,"COMPLETADA",false)));x.tareas.estado(x.a(x.prof),UUID.randomUUID(),r.id(),new TareasPersonales.Cambio(0,"COMPLETADA",true));assertEquals(2,x.tareas.historial(x.a(x.prof),r.id()).size());denied(409,()->x.tareas.estado(x.a(x.prof),UUID.randomUUID(),r.id(),new TareasPersonales.Cambio(1,"PENDIENTE",false)));}
 @Test void contextoDeTareaEsInmutableYNuncaSeImponeResponsable(){var r=x.tareas.crear(x.a(x.prof),UUID.randomUUID(),tarea(null,null));denied(409,()->x.tareas.editar(x.a(x.prof),UUID.randomUUID(),r.id(),tarea("CASO",x.caso())));denied(400,()->x.tareas.crear(x.a(x.prof),UUID.randomUUID(),tarea("CASO",null)));denied(400,()->x.tareas.crear(x.a(x.prof),UUID.randomUUID(),tarea(null,UUID.randomUUID())));denied(400,()->x.tareas.crear(x.a(x.prof),UUID.randomUUID(),tarea("COMUNICACION",x.manual())));var e=tarea(null,null);denied(403,()->x.tareas.crear(x.a(x.ti),UUID.randomUUID(),new TareasPersonales.Edicion(0,e.titulo(),e.descripcion(),null,null,null,null,"NORMAL",null,null,x.prof)));}
 @Test void preparacionSeguimientoYRelacionesNoCambianIngresoNiCreanRequerimiento(){UUID com=x.manual(),key=UUID.randomUUID();var r=s.crear(x.a(x.prof),key,ed(com));assertEquals(r,s.crear(x.a(x.prof),key,ed(com)));assertEquals("EN_PREPARACION",s.leer(x.a(x.prof),r.id()).estado());s.preparar(x.a(x.prof),UUID.randomUUID(),r.id(),new SolicitudesInstitucionales.Preparacion(0,"RESPUESTA","Borrador aún no enviado",null,null));s.seguimiento(x.a(x.prof),UUID.randomUUID(),r.id(),new SolicitudesInstitucionales.Seguimiento(1,"Contacto pendiente"));assertEquals(3,s.historial(x.a(x.prof),r.id()).size());assertEquals(1,s.seguimientos(x.a(x.prof),r.id()).size());assertEquals(com,s.relaciones(x.a(x.prof),r.id()).comunicacion());assertTrue(s.relaciones(x.a(x.prof),r.id()).requerimientos().isEmpty());assertEquals(0,count("core_requirement"));assertEquals(0,count("core_case"));assertEquals(1,count("communication_registry"));assertNull(x.core.detalle(x.a(x.prof),com).respuestaDirecta());assertEquals(2,service().leer(x.a(x.prof),r.id()).revision());}
 @Test void origenNoSeCambiaNiSeReutilizaClaveConDatosDiferentes(){UUID com=x.manual(),key=UUID.randomUUID();var r=s.crear(x.a(x.prof),key,ed(com));denied(409,()->s.crear(x.a(x.prof),key,ed(x.manual())));denied(409,()->s.editar(x.a(x.prof),UUID.randomUUID(),r.id(),ed(x.manual())));s.editar(x.a(x.prof),UUID.randomUUID(),r.id(),new SolicitudesInstitucionales.Edicion(0,com,"Título actualizado",""));denied(409,()->s.preparar(x.a(x.prof),UUID.randomUUID(),r.id(),new SolicitudesInstitucionales.Preparacion(0,"RESPUESTA","No vigente",null,null)));}
 @Test void solicitudNoConcedeAccesoPorCargoUuidOSerDeLaMismaUnidad(){UUID id=solicitud();for(String person:List.of(x.ti,x.dist,x.head,x.otro)){denied(404,()->s.leer(x.a(person),id));assertTrue(s.listar(x.a(person),null).isEmpty());denied(404,()->s.historial(x.a(person),id));denied(404,()->s.seguimientos(x.a(person),id));denied(404,()->s.decisionPendiente(x.a(person),id));}denied(404,()->s.crear(x.a(x.otro),UUID.randomUUID(),ed(s.leer(x.a(x.prof),id).comunicacion())));}
 @Test void perdidaDeAccesoAlIngresoOcultaSolicitudTareaYNotificacion(){UUID c=x.caso(),com=x.core.caso(x.a(x.prof),c).comunicacionId();UUID id=s.crear(x.a(x.head),UUID.randomUUID(),ed(com)).id();UUID t=x.tareas.crear(x.a(x.head),UUID.randomUUID(),tarea("SOLICITUD",id)).id();x.notices.proyectar();var old=x.a(x.head);var account=x.ids.cuentas(x.ti).stream().filter(a->a.id().equals(x.head)).findFirst().orElseThrow();x.ids.revocar(x.ti,x.head,account.asignaciones().getFirst().get("id").toString());denied(403,()->s.leer(old,id));denied(404,()->s.leer(x.a(x.head),id));denied(404,()->x.tareas.leer(x.a(x.head),t));assertTrue(x.notices.listar(x.a(x.head),0,50).items().isEmpty());}
 @Test void respuestaCanalizacionYEscalamientoSiguenCerradosInclusoParaAutor(){UUID id=solicitud();for(String kind:List.of("RESPUESTA","CANALIZACION","ESCALAMIENTO")){var v=s.leer(x.a(x.prof),id);boolean response=kind.equals("RESPUESTA");s.preparar(x.a(x.prof),UUID.randomUUID(),id,new SolicitudesInstitucionales.Preparacion(v.revision(),kind,"Preparación sintética",response?null:"UPR",response?null:"DEMO_SEDE_A"));var error=assertThrows(FalloTecnico.class,()->s.decisionPendiente(x.a(x.prof),id));assertEquals(409,error.status);}assertEquals(0,count("core_case"));assertEquals(0,count("core_requirement"));assertEquals(0,count("distribution_event"));}
 @Test void validacionesNoDejanEfectosParciales(){denied(400,()->s.crear(x.a(x.prof),UUID.randomUUID(),new SolicitudesInstitucionales.Edicion(0,x.manual()," ","")));UUID id=solicitud();denied(400,()->s.preparar(x.a(x.prof),UUID.randomUUID(),id,new SolicitudesInstitucionales.Preparacion(0,"CANALIZACION","Borrador","UPR","NO_EXISTE")));denied(400,()->s.seguimiento(x.a(x.prof),UUID.randomUUID(),id,new SolicitudesInstitucionales.Seguimiento(0," ")));assertEquals(1,count("request_history"));assertEquals(0,count("request_followup"));}
 @Test void falloDePersistenciaRevierteSolicitudComandoYEvento(){x.d.ddl(st->st.execute("ALTER TABLE request_history ADD CONSTRAINT test_request_block CHECK(snapshot_doc NOT LIKE '%BLOQUEO_U5%')"));try{assertThrows(org.springframework.dao.DataAccessException.class,()->s.crear(x.a(x.prof),UUID.randomUUID(),new SolicitudesInstitucionales.Edicion(0,x.manual(),"BLOQUEO_U5","")));}finally{x.d.ddl(st->st.execute("ALTER TABLE request_history DROP CONSTRAINT test_request_block"));}assertEquals(0,count("institution_request"));assertEquals(0,count("request_command"));assertEquals(0,count("workflow_event"));}
 @Test void reintentosConcurrentesAcotadosCreanUnaSolicitudYUnHistorial()throws Exception{UUID key=UUID.randomUUID();var e=ed(x.manual());var a=x.a(x.prof);try(var pool=Executors.newFixedThreadPool(2)){var r=pool.invokeAll(List.of(()->s.crear(a,key,e),()->s.crear(a,key,e)));assertEquals(r.get(0).get(),r.get(1).get());}assertEquals(1,count("institution_request"));assertEquals(1,count("request_history"));}
 @Test void avisosYRecordatoriosSeRecuperanSinDuplicarNiDifundirTexto(){UUID id=solicitud();UUID task=x.tareas.crear(x.a(x.prof),UUID.randomUUID(),tarea("SOLICITUD",id)).id();x.tareas.temporales();for(int i=0;i<5;i++)x.notices.proyectar();int before=count("institution_notification");new TareasPersonales(x.d.db,x.recursos,x.d.mapper,x.tiempo).temporales();new NotificacionesInstitucionales(x.d.db,x.cat,x.recursos,x.tiempo).proyectar();assertEquals(before,count("institution_notification"));assertTrue(x.notices.listar(x.a(x.prof),0,50).items().stream().anyMatch(n->n.ruta().equals("solicitudes/"+id)));assertTrue(x.notices.listar(x.a(x.otro),0,50).items().isEmpty());assertEquals("SOLICITUD",x.tareas.leer(x.a(x.prof),task).tipoRecurso());assertEquals(1,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_notification WHERE category='TAREA_RECORDATORIO'",Integer.class));assertEquals(0,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM notification_outbox WHERE state='ACCEPTED_BY_GRAPH'",Integer.class));}
 @Test void tareaIndependienteDeTiNoAbreContenidoYLasRelacionesExigenAccesoPorCaso(){var t=x.tareas.crear(x.a(x.ti),UUID.randomUUID(),tarea(null,null));assertNull(x.tareas.leer(x.a(x.ti),t.id()).recurso());UUID c=x.caso(),com=x.core.caso(x.a(x.prof),c).comunicacionId();var id=s.crear(x.a(x.dist),UUID.randomUUID(),ed(com)).id();assertEquals(1,s.relaciones(x.a(x.dist),id).requerimientos().size());assertTrue(s.relaciones(x.a(x.dist),id).casos().isEmpty());}
}
